/// The `n` big-endian cells of `w` bytes of a table.
const fn cells<const N: usize>(b: &[u8], w: usize) -> [u128; N] {
    let mut o = [0u128; N];
    let mut i = 0;
    while i < N {
        let mut j = 0;
        while j < w {
            o[i] = (o[i] << u8::BITS) | b[i * w + j] as u128;
            j += 1;
        }
        i += 1;
    }
    o
}
